1	// Generate consumer navigation from the existing supported-declaration census.
2	const assert = require('node:assert/strict');
3	const fs = require('node:fs');
4	const os = require('node:os');
5	const path = require('node:path');
6	const { execFileSync } = require('node:child_process');
7	const packageName = 'configurable-tree-traversal';
8	const anchor = (name) => `symbol-${name}`;
9	const specifier = (entry) =>
10	  packageName + (entry === '.' ? '' : entry.slice(1));
11	const declarationPath = (location) =>
12	  location.replace(/:\d+$/, '').replace(/^\.\//, '');
13	// Inline declaration imports are relative to declaration modules, not supported
14	// consumer import suggestions. Show their type names; routes are listed separately.
15	const displayType = (text) =>
16	  text.replace(/import\(["'][^"']+["']\)\.([\w$]+)/g, '$1');
17	const cell = (text) =>
18	  displayType(text)
19	    .replace(/&/g, '&amp;')
20	    .replace(/</g, '&lt;')
21	    .replace(/>/g, '&gt;')
22	    .replace(/\|/g, '&#124;')
23	    .replace(/\r?\n/g, ' ');
24	// Semantic exceptions precede filename grouping: callbacks, observations and
25	// source protocols can share declaration files while owning different contracts.
26	const symbolContracts = {
27	  core: ['api-compatibility', 'reference.md#api-compatibility'],
28	  TreeTraversalEvent: [
29	    'traversal-orders',
