60	  ],
61	  AsyncDagDiscoverySource: [
62	    'source-callback-contexts',
63	    'examples/dag-prerequisite-resolution-example.ts',
64	  ],
65	  TreeSource: ['source-callback-contexts', 'reference.md#abstract-trees'],
66	  AsyncTreeSource: [
67	    'source-callback-contexts',
68	    'examples/async-adapter-example.ts',
69	  ],
70	  TreeChildResolutionContext: [
71	    'source-callback-contexts',
72	    'reference.md#source-callback-contexts',
73	  ],
74	  DagChildResolutionContext: [
75	    'source-callback-contexts',
76	    'reference.md#source-callback-contexts',
