96	function contractFor(name, locations) {
97	  if (Object.hasOwn(symbolContracts, name)) return symbolContracts[name];
98	  const source = locations.join(' ');
99	  if (/DagProgress/.test(source))
100	    return ['dag-summary-schema', 'examples/agent-orchestration-example.ts'];
101	  if (/coordinateDag/.test(source))
102	    return ['ticket-coordination', 'examples/agent-api-foundations-example.ts'];
103	  if (/DagInspection|inspectDag/.test(source))
104	    return [
105	      'dag-dependency-queries-and-explanations',
106	      'examples/dag-inspection-example.ts',
107	    ];
108	  if (/DagRevision|reviseDag|diffDagDefinition/.test(source))
109	    return ['validated-dag-revisions', 'examples/dag-revision-example.ts'];
110	  if (/DagFragment|dagFragments/.test(source))
111	    return [
112	      'dag-fragments-and-composition',
113	      'examples/dag-fragments-example.ts',
114	    ];
115	  if (/PreparedDag|prepareDag/.test(source))
116	    return [
117	      'reusable-prepared-dags',
118	      'examples/agent-api-foundations-example.ts',
119	    ];
120	  if (/DagDefinition|defineDag/.test(source))
121	    return [
122	      'materialized-dag-definitions',
123	      'examples/dag-fragments-example.ts',
124	    ];
125	  if (/\/sources\//.test(source))
126	    return ['collection-and-forest-sources', 'examples/quickstart-example.ts'];
127	  if (/errors\//.test(source))
128	    return [
129	      'validation-results-and-failures',
130	      'reference.md#narrow-invalid-issues',
131	    ];
132	  if (/graph-walk/.test(source))
133	    return [
134	      /Options|Limits/.test(name)
135	        ? 'options-and-defaults'
136	        : 'general-graph-walking',
137	      'examples/graph-walk-context-example.ts',
138	    ];
139	  if (/rewrite-object|Mutation|MutationBinder/.test(source + name))
140	    return ['rewrite-objects', 'examples/rewrite-object-example.ts'];
141	  if (/traversable-object/.test(source))
142	    return ['traverse-an-object', 'examples/traversable-object-example.ts'];
143	  if (
144	    /ResolvedGraphView|ResolvedTree|Vertex\.d|CTTRef|graph\/types/.test(source)
145	  )
146	    return [
147	      'views-handles-identity-and-paths',
148	      'reference.md#views-handles-identity-and-paths',
149	    ];
150	  if (/TraversableTree|TraversableGraph|TreeTypeParameters/.test(source))
151	    return ['source-callback-contexts', 'examples/async-adapter-example.ts'];
152	  if (/Visitor|ChildHintTransformer/.test(source + name))
153	    return ['visitors-and-commands', 'reference.md#visitors-and-commands'];
154	  if (/Options|Config|IndexRange/.test(source + name))
155	    return [
156	      'options-and-defaults',
157	      'examples/configuration-patches-example.ts',
158	    ];
159	  if (/depth-first/.test(source))
160	    return ['traversal-orders', 'examples/traversable-object-example.ts'];
161	  if (/breadth-first/.test(source))
162	    return ['breadth-first-traversal', 'examples/breadth-first-example.ts'];
163	  if (/dag-traversal/.test(source))
164	    return ['dag-traversal', 'examples/dag-workflow-example.ts'];
165	  return [
166	    'inspection-and-execution',
167	    'examples/graph-walk-references-example.ts',
168	  ];
169	}
170	function renderApiIndex(census) {
171	  const byName = new Map();
172	  const declarations = new Map(census.declarations.map((d) => [d.location, d]));
173	  for (const binding of census.bindings) {
174	    if (!byName.has(binding.name)) byName.set(binding.name, []);
175	    byName.get(binding.name).push(binding);
176	  }
177	  const names = [...byName.keys()].sort();
178	  const routes = Object.entries(census.exports).filter(
179	    ([, value]) => value && typeof value === 'object',
180	  );
181	  let text = '# Public API symbol index\n\n';
182	  text +=
183	    '[Documentation map](index.md) · [Behavior reference](reference.md) · [Upgrade checklist](migration-api-distinctions.md)\n\n';
184	  text +=
185	    'These declarations describe the [unreleased source checkout](../README.md#install). Look up a current exported name below, then follow its owning contract and runnable example. Public import routes are exhaustive for each symbol; declaration-module paths are not consumer imports.\n\n';
186	  text += `Generated from the supported declaration census: **${names.length} public symbols**, **${census.bindings.length} export bindings**, **${routes.length} runtime entry points**. Run \`npm run docs:api\` to regenerate; package verification rejects stale output.\n\n`;
187	  text +=
188	    'Declaration excerpts preserve overloads and public members; referenced support types can be declaration-local and are not additional importable exports. Inline declaration-relative type imports are displayed by type name. These are declaration excerpts, not standalone programs; the linked guide examples are compiled and executed against the packed package. Runtime failures/defaults belong to the linked behavior contract.\n\n';
189	  text +=
190	    '## Lookup\n\n| Symbol | Availability | Contract |\n| --- | --- | --- |\n';
191	  for (const name of names) {
192	    const bindings = byName.get(name);
193	    const [contract] = contractFor(
194	      name,
195	      bindings.flatMap((b) => b.declarations),
196	    );
197	    text += `| [${name}](#${anchor(name)}) | ${
198	      bindings.some((b) => b.runtime)
199	        ? 'Runtime value and type surface'
200	        : 'Type-only'
201	    } | [Behavior](reference.md#${contract}) |\n`;
202	  }
203	  text += '\n## Declarations\n\n';
204	  for (const name of names) {
205	    const bindings = byName.get(name);
206	    const locations = [...new Set(bindings.flatMap((b) => b.declarations))];
207	    const found = locations
208	      .map((location) => declarations.get(location))
209	      .filter(Boolean);
210	    const namespace = routes.find(([, value]) =>
211	      locations.some(
212	        (location) =>
213	          declarationPath(location) === declarationPath(value.require.types),
214	      ),
215	    );
216	    assert(found.length || namespace, `Public declaration missing for ${name}`);
217	    const [contract, example] = contractFor(name, locations);
218	    const exampleLink = example.startsWith('examples/')
219	      ? `https://github.com/dany-fedorov/configurable-tree-traversal/blob/main/${example}`
220	      : example;
221	    text += `<a id="${anchor(name)}"></a>\n\n### ${name}\n\n`;
222	    text += `${
223	      bindings.some((b) => b.runtime)
224	        ? 'Runtime value and public type surface.'
225	        : 'Type-only; no runtime constructor/value.'
226	    } [Owning contract](reference.md#${contract}) · [${
227	      example.startsWith('examples/')
228	        ? 'Runnable example'
229	        : 'Executable snippet'
230	    }](${exampleLink})\n\n`;
231	    text +=
232	      'Supported imports: ' +
233	      [...new Set(bindings.map((b) => specifier(b.entry)))]
234	        .sort()
235	        .map((s) => `\`${s}\``)
236	        .join(', ') +
237	      '.\n\n';
238	    if (namespace && !found.length) {
239	      const members = [
240	        ...new Set(
241	          census.bindings
242	            .filter((b) => b.entry === namespace[0])
243	            .map((b) => b.name),
244	        ),
245	      ].sort();
246	      text +=
247	        `Namespace for \`${specifier(namespace[0])}\`: ` +
248	        members.map((member) => `[${member}](#${anchor(member)})`).join(', ') +
249	        '.\n\n';
250	      continue;
251	    }
252	    text +=
253	      '```ts\n' +
254	      [...new Set(found.map((d) => displayType(d.signature)))].join('\n') +
255	      '\n```\n\n';
256	    const members = new Map();
257	    for (const declaration of found) {
258	      for (const member of declaration.members || [])
259	        members.set(member.name, member.type);
260	    }
261	    if (members.size) {
262	      text +=
263	        '<details>\n<summary>Resolved public members (including inherited/mapped fields)</summary>\n\n| Member | Type |\n| --- | --- |\n';
264	      for (const [member, type] of [...members].sort(([a], [b]) =>
265	        a < b ? -1 : a > b ? 1 : 0,
266	      ))
267	        text += `| \`${member}\` | <code>${cell(type)}</code> |\n`;
268	      text += '\n</details>\n\n';
269	    }
270	  }
271	  return text;
272	}
273	function saveIndex(filename, markdown, check) {
274	  if (check) {
275	    assert(
276	      fs.existsSync(filename) && fs.readFileSync(filename, 'utf8') === markdown,
277	      'Public API index is stale; run npm run docs:api',
278	    );
279	  } else fs.writeFileSync(filename, markdown);
280	}
281	if (require.main === module) {
282	  assert(
283	    process.argv.slice(2).every((arg) => arg === '--check'),
284	    'Usage: node scripts/build-api-index.cjs [--check]',
285	  );
286	  const root = path.resolve(__dirname, '..');
287	  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'ctt-api-index-'));
288	  try {
289	    execFileSync(
290	      process.execPath,
291	      [path.join(__dirname, 'api-clarity-census.cjs'), temporary],
292	      { cwd: root, stdio: 'pipe' },
293	    );
294	    const census = JSON.parse(
295	      fs.readFileSync(path.join(temporary, 'public-api-census.json'), 'utf8'),
296	    );
297	    saveIndex(
298	      path.join(root, 'docs/api-index.md'),
299	      renderApiIndex(census),
300	      process.argv.includes('--check'),
